import type { EngineInterface, Register } from "claude-code";

import { buildCandidates, coversStep, sameCall, SKILL_BLOCKLIST_KEY } from "./candidates";
import type { Candidate } from "./candidates";
import { clip, previousReply, readTurn, summarize, toolCalls } from "./context";
import { askJev, choice, noul, score } from "./jev";
import type { ChoiceAnswer, JevResult, Question } from "./jev";
import { clearLog, readLog, record, recentDecisions, stats } from "./log";
import { buildReport } from "./report";
import { registerView } from "./view";
import { currentMode, MODES } from "./mode";
import { registerPromptClassifier } from "./prompt";
import { registerAgentTypes } from "./agents";
import { registerCompaction } from "./compact";
import { summarizeResult, SUMMARY_MODEL } from "./summarize";
import {
    bestAction,
    bashRiskQuestion,
    difficultyQuestion,
    singleActionQuestion,
    doneQuestion,
    gateBash,
    gateEdit,
    inScopeQuestion,
    adjustEffort,
    effortKeepsCache,
    lowerModel,
    nextActionQuestion,
    pickCandidate,
    route,
    shouldContinue,
} from "./policy";
import type { GateThresholds, Route } from "./policy";

const MAX_TAKES_PER_TURN = 3;
const GATED = new Set(["Bash", "Edit", "Write", "NotebookEdit"]);

/** Short form of a step's tool calls: `Edit app.js ×3, Bash npm test`. */
function summarizeCalls(
    calls: readonly { tool: string; input: Record<string, unknown> }[],
): string {
    if (!calls.length) return "replied";
    const parts = new Map<string, number>();
    for (const c of calls) {
        const target =
            typeof c.input.file_path === "string"
                ? c.input.file_path.split("/").pop()
                : typeof c.input.command === "string"
                  ? c.input.command.replace(/\s+/g, " ").slice(0, 30)
                  : typeof c.input.skill === "string"
                    ? c.input.skill
                    : "";
        const key = target ? `${c.tool} ${target}` : c.tool;
        parts.set(key, (parts.get(key) ?? 0) + 1);
    }
    return [...parts]
        .map(([k, n]) => (n > 1 ? `${k} ×${n}` : k))
        .join(", ");
}

/**
 * Logs Claude's step next to Jev's top action. `agree` means Jev's action
 * would have replaced Claude's whole step (one call, same command once output
 * filters and flags are set aside), so taking it saves one Claude request.
 */
async function recordCompare(
    $: EngineInterface,
    turnId: string,
    step: number,
    request: string,
    answer: ChoiceAnswer,
    candidates: readonly Candidate[],
    toolUses: readonly { name: string; input?: unknown }[],
    measured: boolean,
) {
    const best = bestAction(answer);
    const claudeCalls = toolUses.map((u) => ({
        tool: u.name,
        input: (u.input ?? {}) as Record<string, unknown>,
    }));
    const bestCandidate = candidates.find((c) => c.key === best?.key);
    const agree = Boolean(bestCandidate && coversStep(claudeCalls, bestCandidate));
    const claudeUsedCandidate = claudeCalls.some((c) =>
        candidates.some((k) => coversStep([c], k)),
    );
    const claudeSummary = summarizeCalls(claudeCalls);
    await record($, {
        kind: "compare",
        applied: false,
        text: `Claude: ${claudeSummary} · Jev best ${best?.key ?? "none"}${agree ? " ✓" : ""}`,
        turnId,
        data: {
            request: clip(request, 120),
            step,
            measured,
            claudeSummary,
            pick: answer.choice,
            best: best?.key,
            bestP: best?.p,
            claude: claudeCalls.map((c) => c.tool),
            claudeCalls: claudeCalls.map((c) =>
                clip(String(c.input.command ?? c.input.file_path ?? c.input.skill ?? c.input.query ?? ""), 200),
            ),
            agree,
            claudeUsedCandidate,
        },
    });
}

async function blockSkill($: EngineInterface, name: string) {
    const list = ((await $.store.get(SKILL_BLOCKLIST_KEY)) as string[] | undefined) ?? [];
    if (!list.includes(name))
        await $.store.set(SKILL_BLOCKLIST_KEY, [...list, name]);
}


export const register: Register = (on, options) => {
    const routing =
        options.routing === "model" || options.routing === "off"
            ? options.routing
            : "effort";
    const takeSteps = options.takeSteps !== false;
    const gate = options.gate !== false;
    const doneCheck = options.doneCheck !== false;
    const takeThreshold =
        typeof options.takeThreshold === "number"
            ? options.takeThreshold
            : 0.85;
    const subagents = options.subagents !== false;
    const bypass = options.bypass !== false;
    // Benchmark (2026-10-14): taking steps inside multi-step coding turns only
    // added turns (+6, +3% cost); taking pays off when the whole turn is bypassed.
    const takeOnlyForBypass = options.takeOnlyForBypass !== false;
    const measureSteps = options.measureSteps !== false;
    const SINGLE_ACTION = 0.8;
    const threshold = (key: string, fallback: number) =>
        typeof options[key] === "number" ? (options[key] as number) : fallback;
    const gateThresholds: GateThresholds = {
        dangerAsk: threshold("dangerAsk", 0.5),
        dangerDeny: threshold("dangerDeny", 0.8),
        scopeDeny: threshold("scopeDeny", 0.2),
        editScope: threshold("editScope", 0.15),
    };
    const doneThreshold = threshold("doneThreshold", 0.15);

    registerView(on);
    registerPromptClassifier(on, options, takeThreshold);
    registerAgentTypes(on, options);
    registerCompaction(on, options);

    const turns = new Map<
        string,
        { route?: Route; taken: number; bypassId?: string; bypassAction?: string }
    >();
    // Calls Jev made itself skip the gate: their commands come from a vetted list.
    const ownCalls = new Set<string>();

    on("session.start", async ($, e, next) => {
        await $.command.register({
            name: "jev",
            description:
                "Jev pilot: status, /jev report, /jev export, /jev clear, or switch mode with /jev active|shadow|off",
        });
        return next(e);
    });

    on("command.run", { command: "jev" }, async ($, e) => {
        const arg = e.args.trim();
        if ((MODES as readonly string[]).includes(arg)) {
            await $.store.set("mode", arg);
            return { text: `Jev pilot mode: ${arg}` };
        }
        if (arg === "report") {
            return {
                text: buildReport(
                    await readLog($),
                    takeThreshold,
                    await currentMode($, options.mode),
                ),
            };
        }
        if (arg === "candidates") {
            // Exactly what Jev is offered at step 0 for the last prompt.
            const ctx = await readTurn($);
            const calls = ctx ? toolCalls(ctx.steps) : [];
            const list = await buildCandidates($, ctx?.request ?? "", ctx?.steps ?? [], calls, 0);
            const kind = (c: Candidate) =>
                c.tool === "Skill" ? "Skills" : c.tool === "ToolSearch" ? "Tools to load" : c.tool === "Read" ? "File reads" : "Commands";
            const groups = new Map<string, Candidate[]>();
            for (const c of list) groups.set(kind(c), [...(groups.get(kind(c)) ?? []), c]);
            const sections = [...groups].map(
                ([name, items]) =>
                    `### ${name} (${items.length})\n\n| Option | Description |\n|---|---|\n` +
                    items.map((c) => `| \`${c.key.replace(/\|/g, "\\|")}\` | ${c.description.replace(/\|/g, "\\|").replace(/\s+/g, " ")} |`).join("\n"),
            );
            return {
                text: [
                    `## Jev candidates: ${list.length + 1} options`,
                    `_For the last prompt: "${clip(ctx?.request ?? "(none)", 60)}". Plus \`claude\`: leave the step to Claude._`,
                    ...sections,
                ].join("\n\n"),
            };
        }
        if (arg === "clear") {
            await clearLog($);
            return { text: "Jev pilot: log cleared." };
        }
        if (arg === "export") {
            const log = await readLog($);
            const path = `${await $.session.cwd()}/.jev/decisions.jsonl`;
            try {
                await $.fs.write(
                    path,
                    log.map((entry) => JSON.stringify(entry)).join("\n") + "\n",
                );
                return { text: `Jev pilot: wrote ${log.length} entries to ${path}` };
            } catch (err) {
                return {
                    text: `Jev pilot: could not write ${path}: ${err instanceof Error ? err.message : String(err)}`,
                };
            }
        }
        const counts =
            Object.entries(await stats($))
                .map(([k, v]) => `${k}=${v}`)
                .join(", ") || "none yet";
        const lines = recentDecisions()
            .slice(-10)
            .map(
                (d) =>
                    `- ${d.kind}${d.applied ? "" : " (shadow)"}: ${d.text}${d.ms !== undefined ? ` [${Math.round(d.ms)}ms]` : ""}`,
            );
        return {
            text: [
                `Jev pilot: mode ${await currentMode($, options.mode)}, routing ${routing}, take steps ${takeSteps} (p ≥ ${takeThreshold}), gate ${gate}, done check ${doneCheck}, subagents ${subagents}`,
                `Decisions (all sessions): ${counts}`,
                lines.length
                    ? `Recent:\n${lines.join("\n")}`
                    : "No decisions this session yet.",
                "Full analysis: /jev report",
            ].join("\n"),
        };
    });

    on("turn.complete", async ($, e, next) => {
        turns.delete(e.turnId);
        if (e.reason === "aborted" || e.reason === "error")
            await record($, {
                kind: "turn",
                applied: false,
                text: `turn ${e.reason}`,
                turnId: e.turnId,
                data: { reason: e.reason },
            });
        return next(e);
    });

    // Outcome of each call Jev made itself, for the report.
    on("tool.call", async ($, e, next) => {
        const result = await next(e);
        if (e.tool_use_id && ownCalls.has(e.tool_use_id)) {
            const isError = result.deny !== undefined || result.isError === true;
            await record($, {
                kind: "outcome",
                applied: true,
                text: `${e.tool} ${isError ? "failed" : "ok"}`,
                data: { id: e.tool_use_id, isError },
            });
            // A skill the Skill tool refused is never offered to Jev again.
            const skill = (e as { skill?: unknown }).skill;
            if (isError && e.tool === "Skill" && typeof skill === "string")
                await blockSkill($, skill);
        }
        return result;
    });

    // Each model request: Jev may take the step itself, and at step 0 rates the
    // turn's difficulty to lower effort or model. One Jev request carries both.
    // Every answer is logged; when Claude takes the step, its call is compared
    // with Jev's top action so shadow runs can calibrate the threshold.
    on("turn.step", async function* ($, e, next) {
        const m = await currentMode($, options.mode);
        if (m === "off" || (e.agentId && !subagents)) return yield* next(e);

        const turn = turns.get(e.turnId) ?? { taken: 0 };
        turns.set(e.turnId, turn);

        const ctx = await readTurn($, e.agentId);
        if (!ctx) return yield* next(e);
        const calls = toolCalls(ctx.steps);
        const last = calls.at(-1);

        // Whole-turn bypass: Jev took the one action this simple request needs;
        // a small model reports its result and Claude is not asked at all.
        if (turn.bypassId && e.index > 0) {
            const id = turn.bypassId;
            turn.bypassId = undefined;
            const done = calls.find((c) => c.tool_use_id === id);
            if (m === "active" && done?.text !== undefined) {
                const s = await summarizeResult(
                    $,
                    ctx.request,
                    turn.bypassAction ?? done.tool,
                    done.text,
                );
                await record($, {
                    kind: "bypass",
                    applied: s.ok,
                    text: s.ok
                        ? `answered with ${SUMMARY_MODEL} after ${turn.bypassAction}`
                        : `summary failed (${s.reason}), Claude answers`,
                    turnId: e.turnId,
                    data: {
                        action: turn.bypassAction,
                        model: SUMMARY_MODEL,
                        ...(s.ok ? { usage: s.usage } : { reason: s.reason }),
                    },
                });
                if (s.ok) {
                    const usage = { ...s.usage, model: SUMMARY_MODEL };
                    yield { kind: "text", index: 0, text: s.text };
                    yield { kind: "stop", stopReason: "end_turn", usage };
                    return {
                        turnId: e.turnId,
                        index: e.index,
                        answer: s.text,
                        toolUses: [],
                        stopReason: "end_turn",
                        usage,
                    };
                }
            }
        }

        const questions: Record<string, Question> = {};
        let candidates: Candidate[] = [];
        if (
            takeSteps &&
            turn.taken < MAX_TAKES_PER_TURN &&
            (!takeOnlyForBypass || (bypass && e.index === 0 && !e.agentId))
        ) {
            candidates = (
                await buildCandidates($, ctx.request, ctx.steps, calls, e.index)
            ).filter(
                (c) =>
                    !(last && sameCall(last, { tool: c.tool, input: c.input })),
            );
            if (candidates.length)
                questions.next_action = nextActionQuestion(candidates);
        }
        if (routing !== "off" && e.index === 0)
            questions.difficulty = difficultyQuestion;
        if (bypass && e.index === 0 && questions.next_action && !e.agentId)
            questions.single_action = singleActionQuestion;
        // Effort lowered at step 0 holds for every step of the turn.
        const routed = (step: typeof e) => {
            if (m !== "active" || !turn.route) return step;
            const effort = effortKeepsCache(step.model)
                ? adjustEffort(step.effort, turn.route.effort)
                : undefined;
            const model = lowerModel(step.model, turn.route.model);
            return effort || model
                ? { ...step, ...(effort ? { effort } : {}), ...(model ? { model } : {}) }
                : step;
        };

        if (!Object.keys(questions).length) {
            // Inside a longer turn Jev doesn't take steps, but is asked in
            // parallel with Claude which action it would take, so the take
            // threshold can be measured without adding a delay.
            let measure: Promise<JevResult> | undefined;
            let measured: Candidate[] = [];
            if (measureSteps && takeSteps && e.index > 0 && !e.agentId) {
                measured = (
                    await buildCandidates($, ctx.request, ctx.steps, calls, e.index)
                ).filter((c) => !(last && sameCall(last, { tool: c.tool, input: c.input })));
                if (measured.length)
                    measure = askJev(
                        $,
                        { request: clip(ctx.request, 4000), recent: summarize(ctx.steps), cwd: await $.session.cwd() },
                        { next_action: nextActionQuestion(measured) },
                    );
            }
            const result = yield* next(routed(e));
            const r = await measure;
            const answer = r?.ok ? choice(r.answers, "next_action") : undefined;
            if (answer)
                await recordCompare($, e.turnId, e.index, ctx.request, answer, measured, result.toolUses, true);
            return result;
        }

        // A short follow-up ("yes", "do it") is only rated with confidence
        // when Jev sees what it answers: 0.0–0.2 without, 0.5–0.8 with.
        const previous =
            e.index === 0 && !e.agentId ? await previousReply($) : undefined;
        const state = {
            request: clip(ctx.request, 4000),
            ...(previous ? { previous_reply: previous } : {}),
            recent: summarize(ctx.steps),
            cwd: await $.session.cwd(),
        };
        const r = await askJev($, state, questions);
        if (!r.ok) {
            await record($, {
                kind: "error",
                applied: false,
                text: `unavailable: ${r.error}`,
                ms: r.ms,
                turnId: e.turnId,
            });
            return yield* next(e);
        }

        if (questions.difficulty) {
            const difficulty = score(r.answers, "difficulty");
            turn.route = route(
                difficulty,
                routing === "model" ? "model" : "effort",
            );
            const effort = effortKeepsCache(e.model)
                ? adjustEffort(e.effort, turn.route?.effort)
                : undefined;
            const model = lowerModel(e.model, turn.route?.model);
            const raised = effort === "high";
            const lowered = Boolean((effort && !raised) || model);
            await record($, {
                kind: "route",
                applied: m === "active" && (lowered || raised),
                text: `difficulty ${(difficulty?.score ?? 0).toFixed(2)} → ${lowered || raised ? `${model ?? e.model}, effort ${effort ?? e.effort}` : effortKeepsCache(e.model) ? "no change" : `no change (effort is left alone on ${e.model})`}`,
                ms: r.ms,
                turnId: e.turnId,
                data: {
                    score: difficulty?.score,
                    confidence: difficulty?.confidence,
                    effort,
                    model,
                    lowered,
                    raised,
                },
            });
        }

        const answer = choice(r.answers, "next_action");
        const best = bestAction(answer);
        const singleAction = noul(r.answers, "single_action") ?? 0;
        const pick =
            takeOnlyForBypass && singleAction < SINGLE_ACTION
                ? undefined
                : pickCandidate(answer, candidates, takeThreshold);
        if (answer) {
            const p = answer.probabilities[answer.choice] ?? 0;
            await record($, {
                kind: "take",
                applied: m === "active" && pick !== undefined,
                text: `${answer.choice} (p=${p.toFixed(2)})${pick ? "" : best ? `; best action ${best.key} p=${best.p.toFixed(2)}` : ""}`,
                ms: r.ms,
                turnId: e.turnId,
                data: {
                    pick: answer.choice,
                    p,
                    best: best?.key,
                    bestP: best?.p,
                    candidates: candidates.length,
                    threshold: takeThreshold,
                    wouldTake: pick !== undefined,
                    singleAction: noul(r.answers, "single_action"),
                    agentId: e.agentId,
                },
            });
        }

        if (pick && m === "active") {
            turn.taken += 1;
            const id = `toolu_jev_${crypto.randomUUID().replace(/-/g, "")}`;
            ownCalls.add(id);
            if (singleAction >= SINGLE_ACTION) {
                turn.bypassId = id;
                turn.bypassAction = pick.key;
            }
            yield { kind: "tool", index: 0, id, name: pick.tool };
            yield { kind: "input", index: 0, json: JSON.stringify(pick.input) };
            yield { kind: "stop", stopReason: "tool_use", usage: null };
            return {
                turnId: e.turnId,
                index: e.index,
                answer: "",
                toolUses: [{ name: pick.tool, input: pick.input }],
                stopReason: "tool_use",
                usage: null,
            };
        }

        const result = yield* next(routed(e));

        // Compare Claude's own next call with Jev's top action.
        if (answer)
            await recordCompare($, e.turnId, e.index, ctx.request, answer, candidates, result.toolUses, false);
        return result;
    });

    // Permission gate: only ever tightens what Claude Code already allows.
    on("tool.check", async ($, e, next) => {
        const base = await next(e);
        // Jev's own calls come from the vetted candidate list: approve them so auto
        // mode's classifier doesn't refuse them. A settings deny rule still wins.
        if (e.tool_use_id && ownCalls.has(e.tool_use_id)) {
            if (base.decision === "deny") return base;
            return {
                ...base,
                decision: "allow",
                reason: "Jev pilot: vetted action from its read-only/project-script list",
            };
        }
        if (
            !gate ||
            !GATED.has(e.tool) ||
            (base.decision !== "allow" && base.decision !== "ask") ||
            !e.tool_use_id
        )
            return base;
        const m = await currentMode($, options.mode); // ← add
        if (m === "off") return base;
        const ctx = await readTurn($, e.agentId);
        const input = (e.input ?? {}) as Record<string, unknown>;
        const request = clip(ctx?.request ?? "", 3000);
        const cwd = await $.session.cwd();

        let verdict;
        if (e.tool === "Bash") {
            const r = await askJev(
                $,
                { request, command: String(input.command ?? ""), cwd },
                {
                    risk: bashRiskQuestion,
                    in_scope: inScopeQuestion(
                        "running the command in `command`",
                    ),
                },
            );
            if (!r.ok) return base;
            const risk = score(r.answers, "risk");
            const inScope = noul(r.answers, "in_scope");
            verdict = gateBash(risk, inScope, gateThresholds);
            await record($, {
                kind: "gate",
                applied: m === "active" && verdict !== undefined,
                text: `${verdict?.decision ?? "allow"} Bash: ${clip(String(input.command), 50)}`,
                ms: r.ms,
                data: {
                    tool: "Bash",
                    target: clip(String(input.command), 200),
                    decision: verdict?.decision ?? "allow",
                    danger: risk?.probabilities["2"],
                    inScope,
                },
            });
        } else {
            const change = clip(
                String(
                    input.new_string ?? input.content ?? input.new_source ?? "",
                ),
                1200,
            );
            const file = String(input.file_path ?? input.notebook_path ?? "");
            const r = await askJev(
                $,
                { request, tool: e.tool, file, change, cwd },
                {
                    in_scope: inScopeQuestion(
                        "this change to the file in `file`",
                    ),
                },
            );
            if (!r.ok) return base;
            const inScope = noul(r.answers, "in_scope");
            verdict = gateEdit(inScope, gateThresholds);
            await record($, {
                kind: "gate",
                applied: m === "active" && verdict !== undefined,
                text: `${verdict?.decision ?? "allow"} ${e.tool}: ${file}`,
                ms: r.ms,
                data: {
                    tool: e.tool,
                    target: file,
                    decision: verdict?.decision ?? "allow",
                    inScope,
                },
            });
        }
        // Only ever tighter: allow → ask/deny, ask → deny.
        if (!verdict || m !== "active") return base;
        const tighter =
            verdict.decision === "deny" || base.decision === "allow";
        return tighter
            ? { ...base, decision: verdict.decision, reason: verdict.reason }
            : base;
    });

    // Done check: when Claude stops, send it back once if the request looks unfinished.
    on("classic.Stop", async ($, e, next) => {
        if (!doneCheck || e.stop_hook_active) return next(e);
        const m = await currentMode($, options.mode);
        if (m === "off") return next(e);
        // Waiting on background work (a subagent, a background command) is not
        // stopping early: that work will wake the session when it finishes.
        const waitingOn = e.background_tasks?.length ?? 0;
        if (waitingOn > 0) {
            await record($, {
                kind: "done",
                applied: false,
                text: `skipped: waiting on ${waitingOn} background task(s)`,
                data: { skipped: "background", continued: false },
            });
            return next(e);
        }

        const ctx = await readTurn($);
        if (!ctx) return next(e);
        const r = await askJev(
            $,
            {
                request: clip(ctx.request, 3000),
                final_message: clip(e.last_assistant_message ?? "", 2000),
                recent: summarize(ctx.steps),
            },
            { done: doneQuestion },
        );
        if (!r.ok) return next(e);
        const done = noul(r.answers, "done");
        const unfinished = shouldContinue(done, doneThreshold);
        await record($, {
            kind: "done",
            applied: m === "active" && unfinished,
            text: unfinished
                ? `not finished (p=${(done ?? 0).toFixed(2)}), continuing`
                : `finished (p=${(done ?? 0).toFixed(2)})`,
            ms: r.ms,
            data: { p: done, continued: unfinished },
        });
        if (!unfinished) return next(e);
        const below = await next(e);
        if (m !== "active" || below.block) return below;
        return {
            ...below,
            block: "Jev: the user's request doesn't look finished yet. Continue with what remains. If it is actually complete, say so in one line.",
        };
    });
};

files.hooks/candidates.ts:
import type { EngineInterface, SessionMessage, ToolUseSummary } from 'claude-code'

// Actions Jev may take itself. Code builds the list; Jev only picks from it, so
// every argument is a known value and never generated text.
export type Candidate = {
  /** Option key shown to Jev, e.g. `read src/app.ts` or `run npm test`. */
  key: string
  description: string
  tool: 'Read' | 'Bash' | 'Skill' | 'ToolSearch'
  input: Record<string, unknown>
}

const MAX_READS = 8
const MAX_SEARCHES = 3
const SAFE_SCRIPT = /^(test|tests|lint|build|typecheck|type-check|check|test:[\w:-]+|lint:[\w:-]+)$/
// Built-in CLI commands the command list can report as user commands but the
// Skill tool refuses (`/diff` did). Failed skills are also blocklisted at run time.
export const BUILTIN_COMMANDS = new Set(
  ('add-dir agents bug clear compact config context cost diff doctor exit export help hooks ide init ' +
    'install-github-app login logout mcp memory model permissions plugin pr-comments release-notes resume ' +
    'review rewind status statusline terminal-setup theme upgrade usage vim').split(' '),
)

export const SKILL_BLOCKLIST_KEY = 'skillBlocklist'

const SAFE_MAKE = /^(test|tests|check|lint|build|typecheck)$/
// Paths like src/app.ts, ./README.md, /abs/x.json: something with a file extension.
const PATH = /(?:^|[\s`'"(\[])((?:~|\.{1,2})?\/?[\w@.-]+(?:\/[\w@.-]+)*\.[A-Za-z][A-Za-z0-9]{0,7})(?=$|[\s`'"),:;\]])/g
// Terms the user quoted: `useAuth`, "TODO: fix".
const QUOTED = /`([^`\n]{3,60})`|"([^"\n]{3,60})"/g

export function mentionedPaths(texts: readonly string[]): string[] {
  const seen = new Set<string>()
  for (const text of texts) {
    for (const m of text.matchAll(PATH)) {
      const p = m[1]!
      if (/^\d/.test(p) || /^https?:/.test(p) || p.includes('..')) continue
      seen.add(p)
    }
  }
  return [...seen]
}

export function quotedTerms(text: string): string[] {
  const seen = new Set<string>()
  for (const m of text.matchAll(QUOTED)) {
    const term = (m[1] ?? m[2] ?? '').trim()
    if (term.length >= 3 && !term.includes("'") && !/^[\w./@~-]+\.[A-Za-z]{1,8}$/.test(term)) seen.add(term)
  }
  return [...seen].slice(0, MAX_SEARCHES)
}

// Never offered for reading: Claude Code's temp and task folders (a subagent's
// `.output` file is its whole transcript and floods the context), system temp
// dirs, and Claude's own config tree.
const UNSAFE_PATH = /(^|\/)(tmp|private\/tmp|private\/var\/folders|var\/folders)\/|\/\.claude\/|\/tasks\/[^/]+\.output$|\.output$|\.jsonl$/
// Inside the project only transcripts are refused, so a project that lives in
// a temp dir (a scratch copy, a benchmark) can still be read.
const TRANSCRIPT = /\/tasks\/[^/]+\.output$|\.output$|\.jsonl$/
export const isSafeToOffer = (file: string, cwd?: string) =>
  cwd && file.startsWith(`${cwd}/`) ? !TRANSCRIPT.test(file) : !UNSAFE_PATH.test(file)

const absolute = (cwd: string, p: string) => (p.startsWith('/') ? p : `${cwd}/${p.replace(/^\.\//, '')}`)

export function sameCall(a: { tool: string; input: Record<string, unknown> }, b: { tool: string; input: Record<string, unknown> }) {
  if (a.tool !== b.tool) return false
  if (a.tool === 'Read') return a.input.file_path === b.input.file_path
  if (a.tool === 'Bash') return String(a.input.command).trim() === String(b.input.command).trim()
  if (a.tool === 'Skill') return a.input.skill === b.input.skill
  if (a.tool === 'ToolSearch') return a.input.query === b.input.query
  return false
}

/**
 * What a shell command does, for comparison: each `&&`/`;`/newline part, cut
 * at its first pipe (`| tail`, `| grep` only filter the output), without
 * redirections, `cd` and `echo`, reduced to its command words (flags, paths
 * and numbers dropped). `git status; git diff --stat 2>&1 | head` and
 * `git status --short && git diff --stat` both give `git diff|git status`.
 */
export function commandKey(command: string): string {
  const parts = new Set<string>()
  for (const raw of command.split(/&&|\|\||;|\n/)) {
    const seg = raw.split(/(?<!\|)\|(?!\|)/)[0]!.replace(/\d?>&\d|\d?>\s*\/dev\/null/g, '').trim()
    if (!seg || /^(cd|echo|printf|set|export)\b/.test(seg)) continue
    const tokens = seg.split(/\s+/)
    const words = [tokens[0]!, ...tokens.slice(1).filter(t => /^[a-z][\w:-]*$/.test(t))]
    parts.add(words.slice(0, words[1] === 'run' || words[1] === 'exec' ? 3 : 2).join(' '))
  }
  return [...parts].sort().join('|')
}

/** Same action: identical, or for shell commands the same `commandKey`. */
export function equivalentCall(a: { tool: string; input: Record<string, unknown> }, b: { tool: string; input: Record<string, unknown> }) {
  if (sameCall(a, b)) return true
  if (a.tool !== 'Bash' || b.tool !== 'Bash') return false
  const ka = commandKey(String(a.input.command ?? ''))
  return ka !== '' && ka === commandKey(String(b.input.command ?? ''))
}

/** Jev's action would have replaced Claude's whole step: one call, equivalent. */
export function coversStep(claude: readonly { tool: string; input: Record<string, unknown> }[], jev: { tool: string; input: Record<string, unknown> }) {
  return claude.length === 1 && equivalentCall(claude[0]!, jev)
}

const bash = (command: string, description: string): Candidate => ({
  key: `run ${command}`,
  description,
  tool: 'Bash',
  input: { command, description },
})

export async function buildCandidates(
  $: EngineInterface,
  request: string,
  steps: readonly SessionMessage[],
  calls: readonly ToolUseSummary[],
  stepIndex: number,
): Promise<Candidate[]> {
  const cwd = await $.session.cwd()
  const out: Candidate[] = []
  const has = (file: string) => $.fs.exists(`${cwd}/${file}`).catch(() => false)

  // Files named in the request or the turn's text/tool output, not yet read this turn.
  const texts = [request, ...steps.map(m => m.text), ...calls.map(c => c.text ?? '')]
  const alreadyRead = new Set(calls.filter(c => c.tool === 'Read').map(c => String(c.input.file_path)))
  let reads = 0
  for (const p of mentionedPaths(texts)) {
    if (reads >= MAX_READS) break
    if (p.startsWith('~')) continue
    const file = absolute(cwd, p)
    if (alreadyRead.has(file) || !isSafeToOffer(file, cwd)) continue
    const stat = await $.fs.stat(file).catch(() => undefined)
    if (stat?.kind !== 'file' || stat.size > 2_000_000) continue
    out.push({ key: `read ${p}`, description: `Read the file ${p}`, tool: 'Read', input: { file_path: file } })
    reads += 1
  }

  // Searches for terms the user quoted.
  for (const term of quotedTerms(request)) {
    out.push(bash(`grep -rnF --exclude-dir=node_modules --exclude-dir=.git -- '${term}' .`, `Search the project for the text "${term}"`))
  }

  // Read-only git commands.
  if (await has('.git')) {
    // One "what changed" option: status and diff --stat as two options split
    // Jev's probability (0.75/0.24 live); merged it reaches 0.93.
    out.push(bash('git status --short && git diff --stat', 'Show what changed: which files are modified, staged or untracked, with a per-file count of changed lines'))
    out.push(bash('git diff', 'Show the full line-by-line diff of unstaged changes'))
    out.push(bash('git log --oneline -n 15', 'Show the 15 most recent commits'))
  }

  // The project's own safe scripts and test runners.
  const pkg = await $.fs.read(`${cwd}/package.json`).catch(() => undefined)
  if (typeof pkg === 'string') {
    let scripts: Record<string, string> = {}
    try {
      scripts = (JSON.parse(pkg) as { scripts?: Record<string, string> }).scripts ?? {}
    } catch {}
    const runner = await packageRunner($, cwd)
    for (const name of Object.keys(scripts).filter(n => SAFE_SCRIPT.test(n))) {
      const command = name === 'test' ? `${runner} test` : `${runner} run ${name}`
      out.push(bash(command, `Run the project's "${name}" script (${clipScript(scripts[name]!)})`))
    }
  }
  const makefile = await $.fs.read(`${cwd}/Makefile`).catch(() => undefined)
  if (typeof makefile === 'string') {
    const targets = new Set([...makefile.matchAll(/^([A-Za-z][\w-]*):(?!=)/gm)].map(m => m[1]!))
    for (const t of [...targets].filter(t => SAFE_MAKE.test(t))) out.push(bash(`make ${t}`, `Run the Makefile's "${t}" target`))
  }
  if (await has('Cargo.toml')) {
    out.push(bash('cargo test', 'Run the Rust tests'))
    out.push(bash('cargo check', 'Type-check the Rust project'))
    out.push(bash('cargo clippy', 'Lint the Rust project'))
  }
  if (await has('go.mod')) {
    out.push(bash('go test ./...', 'Run the Go tests'))
    out.push(bash('go vet ./...', 'Vet the Go code'))
    out.push(bash('go build ./...', 'Build the Go packages'))
  }
  if ((await has('pytest.ini')) || (await has('conftest.py')) || /\[tool\.pytest/.test(String(await $.fs.read(`${cwd}/pyproject.toml`).catch(() => '')))) {
    out.push(bash('python -m pytest -q', 'Run the Python tests'))
  }

  // First move of a turn only: a skill to invoke, or a deferred tool to load.
  if (stepIndex === 0) {
    const commands = await $.command.list().catch(() => [])
    const blocked = new Set(((await $.store.get(SKILL_BLOCKLIST_KEY).catch(() => undefined)) as string[] | undefined) ?? [])
    const allSkills = dedupeSkills(
      commands.filter(c => (c.source === 'plugin' || c.source === 'user') && c.name !== 'jev' && !BUILTIN_COMMANDS.has(c.name) && !blocked.has(c.name)),
    )
    // Every skill when the prompt is about skills; otherwise only related ones.
    const skills = /\bskills?\b/i.test(request) ? allSkills : relevant(request, allSkills)
    for (const c of skills) {
      out.push({ key: `skill ${c.name}`, description: `Use the skill or command "${c.name}": ${clipScript(c.description)}`, tool: 'Skill', input: { skill: c.name } })
    }
    const loaded = new Set(calls.filter(c => c.tool === 'ToolSearch').map(c => String(c.input.query)))
    const tools = (await $.tool.list().catch(() => [])).filter(t => t.mcp && !AUTH_TOOL.test(t.name) && !loaded.has(`select:${t.name}`))
    for (const t of relevant(request, tools)) {
      out.push({ key: `load ${t.name}`, description: `Load the tool ${t.name}: ${clipScript(t.description)}`, tool: 'ToolSearch', input: { query: `select:${t.name}`, max_results: 1 } })
    }
  }

  // Jev's choice API takes at most 255 options, one of them "claude".
  return out.slice(0, 254)
}

// MCP sign-in tools are never the next step of a coding turn.
const AUTH_TOOL = /__(authenticate|complete_authentication)$/
const MAX_RELATED = 8
// Words too common in prompts and skill descriptions to show a relation.
const STOPWORDS = new Set(
  ('the and for with this that these those when what which where how why who any all can could would should will ' +
    'you your use used using user users from into onto about over than then them they its it\'s are was were has have ' +
    'had not but also only just some more most very like want need make made create new get set show see one two ' +
    'file files read run runs tool tools skill skills command commands claude code project before after first step ' +
    'please let lets now ok okay yes here there out other each every such via per our we me my is be to of in on at ' +
    'an a or do does did done if so as by up no').split(' '),
)

/** Lowercase content words, light-stemmed so changes/changed/change match. */
export function words(text: string): Set<string> {
  const out = new Set<string>()
  for (const w of text.toLowerCase().split(/[^a-z0-9]+/)) {
    if (w.length < 3 || STOPWORDS.has(w) || /^\d+$/.test(w)) continue
    const stem = w.replace(/(ing|ed|es|e|s)$/, '')
    out.add(stem.length >= 3 && !w.endsWith('ss') ? stem : w)
  }
  return out
}

/**
 * Skills and tools whose name or description shares words with the prompt,
 * best first. A name word counts double; one description word alone is not
 * enough, so generic overlaps ("document", "video") need a second word.
 */
export function relevant<T extends { name: string; description: string }>(prompt: string, items: readonly T[]): T[] {
  const want = words(prompt)
  if (!want.size) return []
  const scored = items.map(item => {
    const name = words(item.name.replace(/^mcp__/, '').replace(/[_:]+/g, ' '))
    const desc = words(item.description)
    let score = 0
    for (const w of want) score += name.has(w) ? 2 : desc.has(w) ? 1 : 0
    return { item, score }
  })
  return scored
    .filter(s => s.score >= 2)
    .sort((a, b) => b.score - a.score)
    .slice(0, MAX_RELATED)
    .map(s => s.item)
}

/**
 * One entry per skill: `anthropic-skills:pdf` and `pdf`, or `youtube-metadata`
 * and `youtube-plugin:youtube-metadata`, are the same skill listed twice. The
 * unprefixed name wins.
 */
export function dedupeSkills<T extends { name: string }>(skills: readonly T[]): T[] {
  const base = (n: string) => n.slice(n.lastIndexOf(':') + 1)
  const byBase = new Map<string, T>()
  for (const s of skills) {
    const kept = byBase.get(base(s.name))
    if (!kept || (kept.name.includes(':') && !s.name.includes(':'))) byBase.set(base(s.name), s)
  }
  return skills.filter(s => byBase.get(base(s.name)) === s)
}

const clipScript = (s: string) => (s.length > 80 ? `${s.slice(0, 80)}…` : s)

async function packageRunner($: EngineInterface, cwd: string) {
  for (const [file, runner] of [['pnpm-lock.yaml', 'pnpm'], ['yarn.lock', 'yarn'], ['bun.lockb', 'bun'], ['bun.lock', 'bun']] as const) {
    if (await $.fs.exists(`${cwd}/${file}`).catch(() => false)) return runner
  }
  return 'npm'
}

